	@Test
	void inheritedOnlyBindingsYieldToLocalOutputsAcrossBuildSides() {
		BindingSet ambient = row("x", "ambient");
		TupleExpr localRight = new Extension(new SingletonSet(),
				new ExtensionElem(new ValueConstant(vf.createLiteral("local")), "x"));
		for (HashJoinIteration.BuildSide side : HashJoinIteration.BuildSide.values()) {
			for (boolean optional : List.of(false, true)) {
				try (HashJoinIteration join = new HashJoinIteration(evaluator.precompile(new SingletonSet()),
						evaluator.precompile(localRight), ambient, optional,
						HashJoinBindingContract.from(new SingletonSet(), localRight),
						new QueryEvaluationContext.Minimal(null), side, null)) {
					List<BindingSet> rows = new ArrayList<>();
					join.forEachRemaining(rows::add);
					assertEquals(List.of(row("x", "local")), rows, "build=" + side + ", optional=" + optional);
				}
				try (HashJoinIteration join = new HashJoinIteration(evaluator.precompile(localRight),
						evaluator.precompile(new SingletonSet()), ambient, optional,
						HashJoinBindingContract.from(localRight, new SingletonSet()),
						new QueryEvaluationContext.Minimal(null), side, null)) {
					List<BindingSet> rows = new ArrayList<>();
					join.forEachRemaining(rows::add);
					assertEquals(List.of(row("x", "local")), rows, "reverse build=" + side + ", optional=" + optional);
				}
			}
		}
	}

