	@Test
	void zeroColumnMultiplicityKeepsVolatileRightIndependent() {
		AtomicInteger evaluations = new AtomicInteger();
		Function volatileFunction = new Function() {
			@Override
			public String getURI() {
				return "urn:test:hash-input-frame-volatile";
			}

			@Override
			public boolean mustReturnDifferentResult() {
				return true;
			}

			@Override
			public Value evaluate(ValueFactory factory, Value... args) {
				return factory.createIRI("urn:evaluation:" + evaluations.incrementAndGet());
			}
		};
		FunctionRegistry.getInstance().add(volatileFunction);
		try {
			List<TupleExpr> lefts = List.of(new EmptySet(), new SingletonSet(),
					new Union(new SingletonSet(), new SingletonSet()));
			for (int count = 0; count < lefts.size(); count++) {
				for (HashJoinIteration.BuildSide side : HashJoinIteration.BuildSide.values()) {
					evaluations.set(0);
					TupleExpr left = lefts.get(count);
					TupleExpr right = new Extension(new SingletonSet(),
							new ExtensionElem(new FunctionCall(volatileFunction.getURI()), "x"));
					try (HashJoinIteration join = new HashJoinIteration(evaluator.precompile(left),
							evaluator.precompile(right), row("x", "ambient"), false,
							HashJoinBindingContract.from(left, right), new QueryEvaluationContext.Minimal(null),
							side, null)) {
						List<BindingSet> rows = new ArrayList<>();
						join.forEachRemaining(rows::add);
						assertEquals(count, rows.size(), "zero-column multiplicity: " + side);
						assertEquals(count == 0 ? 0 : 1, evaluations.get(), "independent RHS evaluation: " + side);
						for (BindingSet result : rows) {
							assertEquals(vf.createIRI("urn:evaluation:1"), result.getValue("x"));
						}
					}
				}
			}
		} finally {
			FunctionRegistry.getInstance().remove(volatileFunction);
		}
	}

